insert into segments (module_id, segment_code, title, script_text,
  tones, tone_map, condition, script_note, section, sort_order,
  coaching, client_should_feel, verbatim, status) values
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Repaso del contrato$vn$), $vn$CONES-002$vn$, $vn$Pages One And Two$vn$, $vn$Haz clic en Continue y haz clic en Share location si te lo pide. La 1ra página contiene la información personal que nos diste. Por favor verifica que esté correcta y avísame cuando termines. La página 2 es la lista de acreedores que elegiste inscribir en el programa. Por favor verifica esto también.$vn$, array[]::text[], $vn$[{"tone": "", "text": "Haz clic en Continue y haz clic en Share location si te lo pide. La 1ra página contiene la información personal que nos diste. Por favor verifica que esté correcta y avísame cuando termines. La página 2 es la lista de acreedores que elegiste inscribir en el programa. Por favor verifica esto también."}]$vn$::jsonb, null, null, $vn$Abrir el portal$vn$, 20, $vn$Give them real time to read. Silence while they check is fine and expected.$vn$, $vn$Nothing here is a surprise.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Repaso del contrato$vn$), $vn$CONES-003$vn$, $vn$Payment Pages$vn$, $vn$La siguiente, página 3, es un calendario de tus pagos con el primer pago de $xxx que se cobrará el XXXX Fecha. Página 4, nos estás autorizando a debitar de tu cuenta $____ durante los próximos ____ meses. Ten en cuenta que tu pago será debitado por Bolton Services Group de tu cuenta bancaria de _______ así que eso es lo que vas a ver en tu estado de cuenta mensual.$vn$, array[]::text[], $vn$[{"tone": "", "text": "La siguiente, página 3, es un calendario de tus pagos con el primer pago de $xxx que se cobrará el XXXX Fecha. Página 4, nos estás autorizando a debitar de tu cuenta $____ durante los próximos ____ meses. Ten en cuenta que tu pago será debitado por Bolton Services Group de tu cuenta bancaria de _______ así que eso es lo que vas a ver en tu estado de cuenta mensual."}]$vn$::jsonb, null, null, $vn$Abrir el portal$vn$, 30, $vn$Plain Talk throughout. Naming what appears on their statement now prevents a confused cancellation call later.$vn$, $vn$I know exactly what will come out and when.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Repaso del contrato$vn$), $vn$CONES-004$vn$, $vn$Adopt And Sign$vn$, $vn$Haz clic en el cuadro amarillo que dice “Sign”, elige el estilo predeterminado. Después haz clic en “adopt and sign”. Esto debería llevarte a la parte inferior de la página 9; por favor desplázate hacia arriba hasta la parte superior de la página 5. Este es el Acuerdo del Cliente, que vamos a revisar juntos.$vn$, array[]::text[], $vn$[{"tone": "", "text": "Haz clic en el cuadro amarillo que dice “Sign”, elige el estilo predeterminado. Después haz clic en “adopt and sign”. Esto debería llevarte a la parte inferior de la página 9; por favor desplázate hacia arriba hasta la parte superior de la página 5. Este es el Acuerdo del Cliente, que vamos a revisar juntos."}]$vn$::jsonb, null, null, $vn$Abrir el portal$vn$, 40, $vn$Slow, literal, one click at a time. Wait for confirmation before the next instruction.$vn$, $vn$I am not lost.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Repaso del contrato$vn$), $vn$CONES-005$vn$, $vn$Agreement Items One To Six$vn$, $vn$Los números 1 al 3 describen los Servicios que Bolton va a realizar. Como puedes ver, es un enfoque integral para fortalecer tu situación financiera y construir tu crédito mediante educación y pasos prácticos para resolver tu deuda. Número 4, política de Apoyo Continuo. (Nombre del Cliente), tienes la opción de continuar con el monitoreo de crédito una vez que termine el plazo. Es voluntario. Número 5 es compensación y pagos. Dice lo mismo que el Calendario de Pagos, pero lo explica con más detalle indicando los detalles de los pagos mensuales. Número 6, Acciones requeridas por ti. Recuerda que tu participación es necesaria y tendrás que comunicarte con tu administrador de cuenta.$vn$, array[]::text[], $vn$[{"tone": "", "text": "Los números 1 al 3 describen los Servicios que Bolton va a realizar. Como puedes ver, es un enfoque integral para fortalecer tu situación financiera y construir tu crédito mediante educación y pasos prácticos para resolver tu deuda. Número 4, política de Apoyo Continuo. (Nombre del Cliente), tienes la opción de continuar con el monitoreo de crédito una vez que termine el plazo. Es voluntario. Número 5 es compensación y pagos. Dice lo mismo que el Calendario de Pagos, pero lo explica con más detalle indicando los detalles de los pagos mensuales. Número 6, Acciones requeridas por ti. Recuerda que tu participación es necesaria y tendrás que comunicarte con tu administrador de cuenta."}]$vn$::jsonb, null, null, $vn$Acuerdo del cliente$vn$, 50, $vn$Steady and clear. Do not speed up because it is familiar to you — it is not familiar to them.$vn$, $vn$I understand what I am agreeing to.$vn$, false, 'published'),
  ((select id from modules where script_id = '116a3615-57b5-4a87-aeac-4256d06dc3df' and language = 'es' and title = $vn$Repaso del contrato$vn$), $vn$CONES-006$vn$, $vn$Agreement Items Seven To Eighteen$vn$, $vn$Número 7 cubre cancelación y reembolsos. Puedes cancelar el acuerdo dentro de 7 días a partir de hoy sin costo. Número 8 es una cláusula estándar de arbitraje. 9 y 10 indican que aceptas hacer negocios por teléfono y electrónicamente, además de permitirnos contactarte hasta que nos indiques lo contrario. 11 al 18 son lenguaje estándar de contrato - échales un vistazo y avísame si tienes alguna pregunta. Por favor haz clic en “sign”.$vn$, array[]::text[], $vn$[{"tone": "", "text": "Número 7 cubre cancelación y reembolsos. Puedes cancelar el acuerdo dentro de 7 días a partir de hoy sin costo. Número 8 es una cláusula estándar de arbitraje. 9 y 10 indican que aceptas hacer negocios por teléfono y electrónicamente, además de permitirnos contactarte hasta que nos indiques lo contrario. 11 al 18 son lenguaje estándar de contrato - échales un vistazo y avísame si tienes alguna pregunta. Por favor haz clic en “sign”."}]$vn$::jsonb, null, null, $vn$Acuerdo del cliente$vn$, 60, $vn$Say the cancellation window clearly rather than sliding past it. Confidence about the exit is what makes the entrance feel safe.$vn$, $vn$I can get out of this if I need to.$vn$, false, 'published');
